-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.112.0',
  '2026-10-03',
  'Пульт ТВ: папки фильмов — «Гарри Поттер» и «Фантастические твари» одной карточкой',
  E'Фильмы одной вселенной теперь собираются в папку: в общем списке это обычная карточка фильма, только с числом внутри — «3 фильма», как у сериала видно число сезонов. Картинка берётся у первого фильма, но её можно поставить свою.\n\nВнутри папки — то же, что у сериала: «Смотреть сначала» играет всё подряд в заданном порядке (для «Гарри Поттера» это и есть главное), «В очередь» ставит папку целиком, «Инфо» показывает описание. А вот содержимое идёт не строчками, как серии, а карточками с постерами: это всё-таки фильмы.\n\nПорядок внутри папки задаётся в админке стрелками — это и есть порядок просмотра. Там же у каждого фильма галочка «только в папке»: с ней он пропадает из общего списка «Фильмы» и виден лишь внутри, без неё — и там, и там. Сериалы объединяются так же.\n\nФайлы на диске при этом не двигаются: папка — это только список и порядок. Убрать папку не значит удалить фильмы — они остаются на месте и возвращаются в общий список.\n\nПопутно кнопка «Инфо» переехала с места под плиткой внутрь самой карточки, вниз постера: список стал вдвое компактнее, а пультом до неё теперь ровный путь — постер, Инфо, В очередь.',
  E'Папка виртуальная (collections.go): запись — список путей и порядок в collections.json, файлы не трогаются. Перекладывать десятки гигабайт на внешнем диске было бы долго и сломало бы «Продолжить просмотр», отметки заставки и кадры — они привязаны к пути; заодно один фильм может быть и в папке, и в общем списке.\n\nПлитка папки (kind collection) встаёт в раздел по виду первого члена и несёт внутри настоящие плитки фильмов — страница играет их тем же кодом, что из общего списка. Члены резолвятся по shortID(path) среди уже разложенных фильмов и сериалов, пропавший молча выпадает (как в плейлистах). Переименование в админке состав переживает: renamePath зовёт collStore.move рядом с moveMarks и moveFrames.\n\nОчередь разворачивает папку в её фильмы при просмотре (watchItems), поэтому plan теперь хранит сам список, а не индекс в watchList: «Смотреть сначала» у папки играет её список, не трогая очередь.\n\nОбложка папки лежит в кэше агента (места на диске у неё нет) — adminImage и дозагрузка частями ходят через общий coverDest. Описание только ручное: поиск по «Гарри Поттер Коллекция» нашёл бы первый фильм серии.\n\n«Инфо» внутри постера — внизу по центру, а не в углу: spatialMove считает score = main + cross*2.5, и в углу кнопка проигрывала соседней плитке. Снизу по центру путь получается прямой: постер → Инфо → В очередь → следующий ряд (проверено прогоном стрелок в браузере).\n\nПроверено в браузере на тестовой библиотеке: папка в разделе фильмов со спрятанными членами, экран папки, очередь из папки и смеси «папка + фильм» (onQueueEnd идёт по трём фильмам и останавливается), папка из сериалов, админка целиком — создание, порядок, галочка, обложка, описание, удаление. Тесты collections_test.go.'
);
-- +goose StatementEnd

